1	/**
2	 * Restaurant Arena event/state hashing primitives and shared trace types.
3	 */
4	
5	import type { ArenaInputRecord } from "./restaurant-game.js";
6	import type { Role } from "./types.js";
7	
8	export const TRACE_V3_VERSION = "restaurant-arena-trace/v3" as const;
9	export const TRACE_V3_CONTRACT_VERSION = "restaurant-arena/v1" as const;
10	
11	/**
12	 * The arena build a trace was recorded against. Kept in step with the package
13	 * version by hand: the overlay bundles this module for the browser, where
14	 * reading package.json at runtime is not available.
15	 */
16	export const ARENA_ENV_VERSION = "0.3.4" as const;
17	
18	export type TraceEventKind =
19	  | "observation"
20	  | "action"
21	  | "player_correction"
22	  | "message"
23	  | "outcome"
24	  | "inspection"
25	  | "hold"
26	  | "hold_cleared"
27	  | "verification_request"
28	  | "verification_response"
29	  | "escalation"
30	  | "handoff"
31	  | "supply_order"
32	  | "supply_delivered"
33	  | "stockout";
34	
35	export type TraceV3Role = Role | "expediter";
36	
37	export interface TraceV3Model {
38	  provider: string;
39	  name: string;
40	  version?: string;
41	}
42	
43	export interface TraceV3Subject {
44	  kind: "order" | "ingredient" | "equipment" | "handoff";
45	  id: string;
46	}
47	
48	/**
49	 * The three keys a grader sorts on. Everything a tool returns beyond them
50	 * (`status: "verified"`, counts, ids) rides alongside untouched.
51	 */
52	export interface TraceV3ToolResult extends Record<string, unknown> {
53	  /** False on every rejected or failed call. Filter on this to select failures. */
54	  ok?: boolean;
55	  /** Model or tool round trip. Absent when no call stood behind the event. */
56	  latencyMs?: number;
57	  /** Time spent waiting for a shared account's request budget before the provider call started. */
58	  queueMs?: number;
59	  /** The provider call itself, excluding queueMs. Absent when the transport cannot separate the two. */
60	  providerMs?: number;
61	  /** Elapsed time since this decision round started, through this worker's own completion. */
62	  roundMs?: number;
63	  /** Absent fields below mean the provider did not report that count, not that it was zero. */
64	  inputTokens?: number;
65	  outputTokens?: number;
66	  cachedInputTokens?: number;
67	  finishReason?: string;
68	  error?: { code: string; message: string; retryable?: boolean } | null;
69	}
70	
71	export interface TraceV3Deletion {
72	  requestId: string | null;
73	  status: "retained" | "requested" | "deleted";
74	}
75	
76	export interface TraceV3Event {
77	  tick: number;
78	  /**
79	   * The decision round this event happened in (#262). Round *r* advances
80	   * ticks 2r-1 and 2r, so a reviewer can line a manager action up against the
81	   * worker turns it shaped without counting ticks by hand.
82	   */
83	  round?: number;
84	  kind: TraceEventKind;
85	  timestamp: string;
86	  stateHash: string;
87	  actorId?: string;
88	  role?: TraceV3Role;
89	  targetRole?: TraceV3Role;
90	  checkpointId?: string;
91	  model?: TraceV3Model;
92	  requestId?: string;
93	  idempotencyKey?: string;
94	  text?: string | null;
95	  observation?: Record<string, unknown> | null;
96	  action?: Record<string, unknown> | null;
97	  toolResult?: TraceV3ToolResult | null;
98	  outcome?: Record<string, unknown> | null;
99	  correctionRationale?: string | null;
100	  correctionCategory?: "safety" | "priority" | "quality" | "pace" | null;
101	  changedDecisionEventId?: string | null;
102	  probeEventId?: string | null;
103	  subject?: TraceV3Subject;
104	  payload?: Record<string, unknown> | null;
105	}
106	
107	export interface RestaurantArenaTraceV3 {
108	  version: typeof TRACE_V3_VERSION;
109	  episodeId: string;
110	  /**
111	   * The one run this trace came from.
112	   *
113	   * `episodeId` names the *scenario* -- `dinner-rush-218220` is the same
114	   * dinner rush every time it is played, and the benchmark fixture leans on
115	   * that. So it cannot identify a session: two people playing the same seed
116	   * export the same `episodeId`, which makes two sessions indistinguishable
117	   * on receipt and a re-export indistinguishable from a new one (#281).
118	   *
119	   * Optional so every v3 export written before this field stays valid. A
120	   * trace without one is a trace whose session cannot be matched, not a
121	   * malformed trace.
122	   */
123	  sessionId?: string;
124	  seed: number;
125	  envVersion: string;
126	  contractVersion: typeof TRACE_V3_CONTRACT_VERSION;
127	  runKind: "live" | "synthetic" | "benchmark";
128	  /** The world at tick 0. Required: without it a trace cannot be replayed. */
129	  initialState: Record<string, unknown>;
130	  events: TraceV3Event[];
131	  deletion: TraceV3Deletion;
132	  replay: {
133	    variation: string;
134	    inputs: ArenaInputRecord[];
135	    finalStateHash: string;
136	    /** Optional so earlier v3 exports remain valid. */
137	    finalRestaurantStateHash?: string;
138	  };
139	  terminal: { status: "active" | "completed" | "abandoned"; tick: number; reason: string | null };
140	}
141	
142	/**
143	 * Pure, deterministic SHA-256 implementation (FIPS 180-4).
144	 * Runs synchronously in any JavaScript runtime (Node, Bun, browser) without external dependencies.
145	 */
146	export function sha256Bytes(bytes: Uint8Array): string {
147	  const K = [
148	    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
149	    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
150	    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
151	    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
152	    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
153	    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
154	    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
155	    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
156	  ];
157	
158	  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
159	  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
160	
161	  const len = bytes.length;
162	  const bitLen = len * 8;
163	  const withPadLen = (((len + 8) >> 6) + 1) << 6;
164	  const padded = new Uint8Array(withPadLen);
165	  padded.set(bytes);
166	  padded[len] = 0x80;
167	  const view = new DataView(padded.buffer);
168	  view.setUint32(withPadLen - 4, bitLen >>> 0, false);
169	  view.setUint32(withPadLen - 8, Math.floor(bitLen / 0x100000000), false);
170	
171	  const w = new Uint32Array(64);
172	
173	  for (let i = 0; i < withPadLen; i += 64) {
174	    for (let j = 0; j < 16; j++) {
175	      w[j] = view.getUint32(i + j * 4, false);
176	    }
177	    for (let j = 16; j < 64; j++) {
178	      const w15 = w[j - 15]!;
179	      const w2 = w[j - 2]!;
180	      const s0 =
181	        ((w15 >>> 7) | (w15 << 25)) ^
182	        ((w15 >>> 18) | (w15 << 14)) ^
183	        (w15 >>> 3);
184	      const s1 =
185	        ((w2 >>> 17) | (w2 << 15)) ^
186	        ((w2 >>> 19) | (w2 << 13)) ^
187	        (w2 >>> 10);
188	      w[j] = (w[j - 16]! + s0 + w[j - 7]! + s1) >>> 0;
189	    }
190	
191	    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
192	
193	    for (let j = 0; j < 64; j++) {
194	      const s1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
195	      const ch = (e & f) ^ (~e & g);
196	      const temp1 = (h + s1 + ch + K[j]! + w[j]!) >>> 0;
197	      const s0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
198	      const maj = (a & b) ^ (a & c) ^ (b & c);
199	      const temp2 = (s0 + maj) >>> 0;
200	
201	      h = g;
202	      g = f;
203	      f = e;
204	      e = (d + temp1) >>> 0;
205	      d = c;
206	      c = b;
207	      b = a;
208	      a = (temp1 + temp2) >>> 0;
209	    }
210	
211	    h0 = (h0 + a) >>> 0;
212	    h1 = (h1 + b) >>> 0;
213	    h2 = (h2 + c) >>> 0;
214	    h3 = (h3 + d) >>> 0;
215	    h4 = (h4 + e) >>> 0;
216	    h5 = (h5 + f) >>> 0;
217	    h6 = (h6 + g) >>> 0;
218	    h7 = (h7 + h) >>> 0;
219	  }
220	
221	  const hex = [h0, h1, h2, h3, h4, h5, h6, h7]
222	    .map((v) => (v >>> 0).toString(16).padStart(8, "0"))
223	    .join("");
224	  return `sha256:${hex}`;
225	}
226	
227	const FLOAT_FIELDS = new Set([
228	  "cash", "coordination", "correctionUptake", "load", "reading",
229	  "reputation", "safetyThreshold", "satisfaction", "waitTime", "waste",
230	]);
231	
232	function serializeJson(value: unknown, pretty: boolean, sortKeys: boolean, level = 0, key?: string): string | undefined {
233	  if (value === undefined) return undefined;
234	  if (value === null || typeof value === "boolean" || typeof value === "string") return JSON.stringify(value);
235	  if (typeof value === "number") {
236	    if (!Number.isFinite(value)) throw new TypeError("canonical JSON does not support non-finite numbers");
237	    return FLOAT_FIELDS.has(key ?? "") && Number.isInteger(value) ? `${value}.0` : JSON.stringify(value);
238	  }
239	  if (Array.isArray(value)) {
240	    const items = value.map((item) => serializeJson(item, pretty, sortKeys, level + 1));
241	    return pretty && items.length > 0
242	      ? `[\n${items.map((item) => `${"  ".repeat(level + 1)}${item ?? "null"}`).join(",\n")}\n${"  ".repeat(level)}]`
243	      : `[${items.map((item) => item ?? "null").join(",")}]`;
244	  }
245	  if (typeof value === "object") {
246	    const record = value as Record<string, unknown>;
247	    const keys = Object.keys(record);
248	    if (sortKeys) keys.sort();
249	    const entries = keys.flatMap((entryKey) => {
250	      const serialized = serializeJson(record[entryKey], pretty, sortKeys, level + 1, entryKey);
251	      return serialized === undefined ? [] : [[entryKey, serialized] as const];
252	    });
253	    return pretty && entries.length > 0
254	      ? `{\n${entries.map(([entryKey, serialized]) => `${"  ".repeat(level + 1)}${JSON.stringify(entryKey)}: ${serialized}`).join(",\n")}\n${"  ".repeat(level)}}`
255	      : `{${entries.map(([entryKey, serialized]) => `${JSON.stringify(entryKey)}:${serialized}`).join(",")}}`;
256	  }
257	  throw new TypeError(`Unsupported JSON value: ${typeof value}`);
258	}
259	
260	/** Backend-compatible JSON: sorted keys and decimal spelling for float fields. */
261	export function canonicalJson(value: unknown): string {
262	  return serializeJson(value, false, true) ?? "null";
263	}
264	
265	export function computeStateHash(data: unknown): string {
266	  const json = typeof data === "string" ? data : canonicalJson(data);
267	  return sha256Bytes(new TextEncoder().encode(json));
268	}
