163	  const withPadLen = (((len + 8) >> 6) + 1) << 6;
164	  const padded = new Uint8Array(withPadLen);
165	  padded.set(bytes);
166	  padded[len] = 0x80;
167	  const view = new DataView(padded.buffer);
168	  view.setUint32(withPadLen - 4, bitLen >>> 0, false);
169	  view.setUint32(withPadLen - 8, Math.floor(bitLen / 0x100000000), false);
170	
171	  const w = new Uint32Array(64);
172	
173	  for (let i = 0; i < withPadLen; i += 64) {
174	    for (let j = 0; j < 16; j++) {
175	      w[j] = view.getUint32(i + j * 4, false);
176	    }
177	    for (let j = 16; j < 64; j++) {
178	      const w15 = w[j - 15]!;
179	      const w2 = w[j - 2]!;
180	      const s0 =
181	        ((w15 >>> 7) | (w15 << 25)) ^
182	        ((w15 >>> 18) | (w15 << 14)) ^
183	        (w15 >>> 3);
184	      const s1 =
185	        ((w2 >>> 17) | (w2 << 15)) ^
186	        ((w2 >>> 19) | (w2 << 13)) ^
187	        (w2 >>> 10);
188	      w[j] = (w[j - 16]! + s0 + w[j - 7]! + s1) >>> 0;
189	    }
190	
191	    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
192	
193	    for (let j = 0; j < 64; j++) {
194	      const s1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
195	      const ch = (e & f) ^ (~e & g);
196	      const temp1 = (h + s1 + ch + K[j]! + w[j]!) >>> 0;
197	      const s0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
198	      const maj = (a & b) ^ (a & c) ^ (b & c);
199	      const temp2 = (s0 + maj) >>> 0;
200	
201	      h = g;
202	      g = f;
203	      f = e;
204	      e = (d + temp1) >>> 0;
205	      d = c;
206	      c = b;
207	      b = a;
208	      a = (temp1 + temp2) >>> 0;
209	    }
210	
211	    h0 = (h0 + a) >>> 0;
212	    h1 = (h1 + b) >>> 0;
213	    h2 = (h2 + c) >>> 0;
214	    h3 = (h3 + d) >>> 0;
215	    h4 = (h4 + e) >>> 0;
216	    h5 = (h5 + f) >>> 0;
217	    h6 = (h6 + g) >>> 0;
218	    h7 = (h7 + h) >>> 0;
219	  }
220	
221	  const hex = [h0, h1, h2, h3, h4, h5, h6, h7]
222	    .map((v) => (v >>> 0).toString(16).padStart(8, "0"))
223	    .join("");
224	  return `sha256:${hex}`;
225	}
226	
227	const FLOAT_FIELDS = new Set([
228	  "cash", "coordination", "correctionUptake", "load", "reading",
229	  "reputation", "safetyThreshold", "satisfaction", "waitTime", "waste",
230	]);
231	
232	function serializeJson(value: unknown, pretty: boolean, sortKeys: boolean, level = 0, key?: string): string | undefined {
233	  if (value === undefined) return undefined;
234	  if (value === null || typeof value === "boolean" || typeof value === "string") return JSON.stringify(value);
235	  if (typeof value === "number") {
236	    if (!Number.isFinite(value)) throw new TypeError("canonical JSON does not support non-finite numbers");
237	    return FLOAT_FIELDS.has(key ?? "") && Number.isInteger(value) ? `${value}.0` : JSON.stringify(value);
238	  }
239	  if (Array.isArray(value)) {
240	    const items = value.map((item) => serializeJson(item, pretty, sortKeys, level + 1));
241	    return pretty && items.length > 0
242	      ? `[\n${items.map((item) => `${"  ".repeat(level + 1)}${item ?? "null"}`).join(",\n")}\n${"  ".repeat(level)}]`
243	      : `[${items.map((item) => item ?? "null").join(",")}]`;
244	  }
245	  if (typeof value === "object") {
246	    const record = value as Record<string, unknown>;
247	    const keys = Object.keys(record);
248	    if (sortKeys) keys.sort();
249	    const entries = keys.flatMap((entryKey) => {
250	      const serialized = serializeJson(record[entryKey], pretty, sortKeys, level + 1, entryKey);
251	      return serialized === undefined ? [] : [[entryKey, serialized] as const];
252	    });
253	    return pretty && entries.length > 0
254	      ? `{\n${entries.map(([entryKey, serialized]) => `${"  ".repeat(level + 1)}${JSON.stringify(entryKey)}: ${serialized}`).join(",\n")}\n${"  ".repeat(level)}}`
255	      : `{${entries.map(([entryKey, serialized]) => `${JSON.stringify(entryKey)}:${serialized}`).join(",")}}`;
256	  }
257	  throw new TypeError(`Unsupported JSON value: ${typeof value}`);
258	}
259	
260	/** Backend-compatible JSON: sorted keys and decimal spelling for float fields. */
261	export function canonicalJson(value: unknown): string {
262	  return serializeJson(value, false, true) ?? "null";
263	}
264	
265	export function computeStateHash(data: unknown): string {
266	  const json = typeof data === "string" ? data : canonicalJson(data);
267	  return sha256Bytes(new TextEncoder().encode(json));
268	}
