22	    game.step("verify_substitution");
23	    for (let i = 0; i < 16; i++) game.step("tick");
24	
25	    expect(game.isOver()).toBe(true);
26	
27	    const timeline = buildArenaTimeline(game);
28	    const html = renderTimelineHtml(timeline);
29	
30	    expect(timeline.milestonesPresented).toEqual(["original_decision", "correction", "later_probe", "outcome"]);
31	    expect(timeline.cards.map((card) => card.tick)).toEqual(game.getRecordedEvents().map((event) => event.tick));
32	    expect(html).toContain("protect safety and verify before substituting");
33	    expect(html).not.toContain("Correction stayed scoped");
34	    expect(html).toContain("This alone does not establish a worker response");
35	    expect(html).toContain("Shift Outcome Metrics");
36	  });
