51	    const parsed = JSON.parse(json);
52	
53	    // Validate using the schema validator
54	    const validation = validateArenaTraceV3(parsed);
55	    expect(validation.valid).toBe(true);
56	    expect(validation.errors).toEqual([]);
57	
58	    // Check against raw schema definition
59	    const schemaPath = join(import.meta.dir, "../contracts/restaurant-arena-trace-v3.schema.json");
60	    const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
61	    expect(parsed.version).toBe("restaurant-arena-trace/v3");
62	    expect(parsed.contractVersion).toBe("restaurant-arena/v1");
63	    expect(parsed.events.length).toBeGreaterThan(0);
64	
65	    for (const req of schema.required) {
66	      expect(parsed[req]).toBeDefined();
67	    }
68	  });
