  type WaitingParty,
} from "./arena-view.js";
import { roundContractFor, type RoundContract, type RoundStatus } from "./rounds.js";
import {
  ACTIVE_ORDER_STATUSES,
  HANDOFF_BY_ORDER_STATUS,
  ROLE_PERMISSIONS,
  projectObservation,
  projectChefObservation,
  projectServerObservation,
