function endGame(
  outcome: "completed" | "abandoned",
  reason: EpisodeEndReason = game?.hasWon() ? "won" : "game_over",
): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  if (outcome === "abandoned" && game.name === "restaurant-arena") (game as unknown as RestaurantGame).markAbandoned(reason);
  const endedAtMs = Date.now();
  const variationId = entry.variations[variationCursor]?.id ?? "classic";
  const localScore = localScoreForCompletion({
    outcome,
    gameId: sessionReceiptId ?? `game_${gameSessionId ?? crypto.randomUUID()}`,
    gameType: entry.id,
    variationId,
    score: game.score(),
    success: game.hasWon(),
    endedAtMs,
    startedAtMs: gameStartedAt,
    platform: "overlay",
  });
  if (localScore) void invoke("append_local_score", { score: localScore }).then(refreshLocalScores).catch(() => undefined);
  if (outcome === "completed") {
    if (savedGame) {
      lastReplay = { entry, variationId, seed: savedGame.seed, actions: [...savedGame.actions],
        ...(game.name === "restaurant-arena" ? { arenaTrace: captureArenaTrace(game as unknown as RestaurantGame, { runKind: "live" }) } : {}) };
    }
    clearSavedGame();
    savedGame = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variationId,
    outcome,
    score: game.score(),
    success: outcome === "completed" && game.hasWon(),
    duration_ms: Math.max(0, endedAtMs - gameStartedAt),
    actions_taken: actionsTaken,
  }, gameSessionId);
  if (activeTrace) {
    const trace = activeTrace;
    activeTrace = undefined;
    cancelTraceFlush();
    submitTrace(trace, reason, outcome === "completed" ? game.score() : undefined);
  }
}

