1878	  private adaptLegacyActionEnvelope(envelope: ActionEnvelope): ActionEnvelope {
1879	    const isLegacyRole = (envelope.role as string) === "expediter";
1880	    const isLegacyActor = envelope.actorId === "worker-expediter";
1881	    const isLegacyTarget = envelope.tool === "send_message" && envelope.arguments?.to === "worker-expediter";
1882	    const isLegacyTargetRole = envelope.arguments?.targetRole === "expediter";
1883	    const isLegacyWorkerId = envelope.arguments?.workerId === "worker-expediter" || envelope.arguments?.workerId === "expediter";
1884	
1885	    if (!isLegacyRole && !isLegacyActor && !isLegacyTarget && !isLegacyTargetRole && !isLegacyWorkerId) {
1886	      return envelope;
1887	    }
1888	
1889	    const role: Role = isLegacyRole ? "supply_lead" : (envelope.role as Role);
1890	    const actorId = isLegacyActor ? "worker-supply_lead" : envelope.actorId;
1891	    let args = envelope.arguments;
1892	    if (isLegacyTarget || isLegacyTargetRole || isLegacyWorkerId) {
1893	      args = { ...args };
1894	      if (args.to === "worker-expediter") args.to = "worker-supply_lead";
1895	      if (args.targetRole === "expediter") args.targetRole = "supply_lead";
1896	      if (args.workerId === "worker-expediter" || args.workerId === "expediter") {
1897	        args.workerId = "worker-supply_lead";
1898	      }
1899	    }
1900	
1901	    return {
1902	      ...envelope,
1903	      role,
1904	      actorId,
1905	      arguments: args,
1906	    };
1907	  }
1908	
1909	  /**
1910	   * Submit an action envelope, recording the call's telemetry alongside it.
1911	   *
1912	   * Rejections are journalled here rather than inside the validation body, so
1913	   * every refusal path — present and future — reaches the trace as an event
1914	   * with `toolResult.ok === false`. A trace that only carried accepted actions
1915	   * would let a model that failed half its turns read as a clean run.
1916	   */
1917	  stepEnvelope(
1918	    rawEnvelope: ActionEnvelope,
1919	    telemetry?: EnvelopeTelemetry,
1920	  ): { accepted: boolean; state: RestaurantState; error?: ActionError } {
1921	    const envelope = this.adaptLegacyActionEnvelope(rawEnvelope);
1922	    return this.recordInput({ kind: "envelope", envelope, ...(telemetry ? { telemetry } : {}) }, () => this.applyRecordedEnvelope(envelope, telemetry));
1923	  }
1924	
1925	  private applyRecordedEnvelope(envelope: ActionEnvelope, telemetry?: EnvelopeTelemetry) {
1926	    const cached = this.idempotencyCache.get(envelope.idempotencyKey);
1927	    if (cached) return cached;
1928	
1929	    // The manager's round budget is enforced here rather than in
1930	    // submitPlayerIntervention because this is the boundary a replay crosses:
1931	    // replay re-applies recorded envelopes directly, so a check made further
1932	    // up would be missing on the way back through and the two runs would
1933	    // diverge on the first envelope the budget refused. It also means a
1934	    // direct stepEnvelope() caller cannot walk around the budget.
1935	    //
1936	    // `undefined` means this envelope draws on no budget at all: a worker's
1937	    // own action, or a manager answering a raised decision.
1938	    const managerKey =
1939	      envelope.actorType === "player" && envelope.tool !== "approve"
1940	        ? this.managerRequestKey(envelope.requestId)
1941	        : undefined;
1942	    // One instruction to the whole floor arrives as four envelopes sharing a
1943	    // request stem. The first is charged; the rest are the same exercise of
1944	    // authority and neither charge nor re-check.
1945	    const alreadyCharged = managerKey !== undefined && managerKey === this.lastChargedManagerRequest;
1946	
1947	    if (managerKey !== undefined && !alreadyCharged && !this.roundStatus().canAct) {
1948	      const error: ActionError = {
1949	        code: "round_budget_exhausted",
1950	        message: `round ${this.roundNumber} already spent its manager envelope; wait for round ${this.roundNumber + 1}`,
1951	        retryable: false,
1952	      };
1953	      this.journalRejectedEnvelope(envelope, error, telemetry);
1954	      return { accepted: false, state: this.state(), error };
1955	    }
1956	
1957	    this.pendingTelemetry = telemetry;
1958	    try {
1959	      const result = this.applyEnvelope(envelope);
1960	      if (!result.accepted && result.error) {
1961	        this.journalRejectedEnvelope(envelope, result.error, telemetry);
1962	        return result;
1963	      }
1964	      // Charged only once the action actually landed. A ticket that turned out
1965	      // to be cancelled, or an order id that matches nothing, costs the manager
1966	      // nothing — they did not get to change anything with it.
1967	      if (managerKey !== undefined && !alreadyCharged) {
1968	        this.lastChargedManagerRequest = managerKey;
1969	        this.spendManagerEnvelope();
1970	      }
1971	      return result;
1972	    } finally {
1973	      this.pendingTelemetry = undefined;
1974	    }
1975	  }
1976	
1977	  /** The rejection as the graders read it: one event, `toolResult.ok` false. */
1978	  private journalRejectedEnvelope(
1979	    envelope: ActionEnvelope,
1980	    error: ActionError,
1981	    telemetry?: EnvelopeTelemetry,
1982	  ): void {
1983	    this.recordEvent({
1984	      tick: this.currentState.episode.tick,
1985	      kind: "action",
1986	      timestamp: envelope.timestamp || this.timestampForTick(this.currentState.episode.tick),
1987	      stateHash: computeStateHash({
1988	        episodeId: envelope.episodeId,
1989	        requestId: envelope.requestId,
1990	        actorId: envelope.actorId,
1991	        tool: envelope.tool,
1992	        rejected: error.code,
1993	        tick: this.currentState.episode.tick,
1994	      }),
1995	      actorId: envelope.actorId,
1996	      role: envelope.role,
1997	      requestId: envelope.requestId,
1998	      idempotencyKey: envelope.idempotencyKey,
1999	      ...(telemetry?.model ? { model: telemetry.model } : {}),
2000	      text: `${STAFF[envelope.role]?.name ?? envelope.role} was refused ${envelope.tool}: ${error.message}`,
2001	      action: { tool: envelope.tool, arguments: envelope.arguments },
2002	      toolResult: {
2003	        ok: false,
2004	        ...telemetryToolResultFields(telemetry),
2005	        error: { code: error.code, message: error.message, retryable: error.retryable },
2006	      },
2007	    });
