1	/**
2	 * The decision-round contract, frozen for issue #262.
3	 *
4	 * Both controllers read their round budget from here — the overlay's human
5	 * manager and the model-driven `WorkerOrchestrator` alike — so neither path
6	 * can quietly grant itself authority the other does not have. A level's
7	 * round count is *derived*, not declared: the tick interval is the frozen
8	 * invariant and the count follows from how long the shift runs.
9	 *
10	 * That is why Saturday Night gets 14 rounds where the other two get 12. It
11	 * runs 28 ticks rather than 24, and trimming it to fit a uniform 12 was
12	 * measured to cost roughly two served orders — about 10% of a cash goal the
13	 * level already only just reaches.
14	 */
15	
16	import { SHIFT_PRESETS, DEFAULT_SHIFT } from "./arena-view.js";
17	
18	/** Simulation ticks advanced at the end of every decision round. Frozen. */
19	export const TICKS_PER_ROUND = 2;
20	
21	/** One manager action or message per round, an explicit no-op included. */
22	export const MANAGER_ENVELOPES_PER_ROUND = 1;
23	
24	export interface RoundContract {
25	  readonly variationId: string;
26	  /** Frozen ticks advanced per round. */
27	  readonly ticksPerRound: number;
28	  /** Decision rounds in the level, derived from `maxTicks / ticksPerRound`. */
29	  readonly rounds: number;
30	  readonly maxTicks: number;
31	  /** Manager envelopes budgeted per round. */
32	  readonly envelopesPerRound: number;
33	}
34	
35	/** Where the shift stands: which round is open and what is left in it. */
36	export interface RoundStatus {
37	  /** 1-based. Never exceeds `totalRounds`. */
38	  readonly round: number;
39	  readonly totalRounds: number;
40	  /** Ticks already advanced inside the open round. */
41	  readonly ticksIntoRound: number;
42	  /** Manager envelopes already spent this round. */
43	  readonly envelopesSpent: number;
44	  readonly envelopesPerRound: number;
45	  /** False once the round's envelope is spent. */
46	  readonly canAct: boolean;
47	}
48	
49	export function roundContractFor(variationId?: string): RoundContract {
50	  const preset = (variationId && SHIFT_PRESETS[variationId]) || DEFAULT_SHIFT;
51	  return {
52	    variationId: preset.id,
53	    ticksPerRound: TICKS_PER_ROUND,
54	    rounds: Math.ceil(preset.maxTicks / TICKS_PER_ROUND),
55	    maxTicks: preset.maxTicks,
56	    envelopesPerRound: MANAGER_ENVELOPES_PER_ROUND,
57	  };
58	}
59	
60	/**
61	 * The round that *contains* `tick` — round *r* advances ticks 2r−1 and 2r, so
62	 * Dinner Rush's oven failure at tick 8 belongs to round 4. Tick 0 is the
63	 * opening manager envelope, before anything has advanced, and reads as
64	 * round 1.
65	 */
66	export function roundForTick(tick: number, ticksPerRound: number = TICKS_PER_ROUND): number {
67	  if (tick <= 0) return 1;
68	  return Math.ceil(tick / ticksPerRound);
69	}
