361	  if (typeof s.seed !== "number" || !Number.isInteger(s.seed)) return false;
362	
363	  // episode
364	  if (typeof s.episode !== "object" || s.episode === null) return false;
365	  const ep = s.episode as Record<string, unknown>;
366	  if (typeof ep.id !== "string" || !ep.id) return false;
367	  if (ep.phase !== "active" && ep.phase !== "complete") return false;
368	  if (typeof ep.tick !== "number" || ep.tick < 0) return false;
369	  if (typeof ep.maxTicks !== "number" || ep.maxTicks < 1) return false;
370	
371	  // clock
372	  if (typeof s.clock !== "object" || s.clock === null) return false;
373	  const clk = s.clock as Record<string, unknown>;
374	  if (typeof clk.minute !== "number" || clk.minute < 0) return false;
375	  if (typeof clk.speed !== "number" || clk.speed < 1) return false;
376	
377	  // tables
378	  if (!Array.isArray(s.tables)) return false;
379	  for (const t of s.tables) {
380	    if (typeof t !== "object" || t === null) return false;
381	    if (typeof t.id !== "string" || typeof t.seats !== "number") return false;
382	    if (t.status !== "empty" && t.status !== "occupied") return false;
383	  }
384	
385	  // orders
386	  if (!Array.isArray(s.orders)) return false;
387	  const validStatuses = new Set([
388	    "queued",
389	    "seated",
390	    "preparing",
391	    "ready",
392	    "served",
393	    "cancelled",
394	  ]);
395	  for (const o of s.orders) {
396	    if (typeof o !== "object" || o === null) return false;
397	    if (typeof o.id !== "string" || !Array.isArray(o.items)) return false;
398	    if (!validStatuses.has(o.status)) return false;
399	    if (o.priority !== "normal" && o.priority !== "high") return false;
400	  }
401	
402	  // inventory
403	  if (typeof s.inventory !== "object" || s.inventory === null) return false;
404	  for (const [k, v] of Object.entries(s.inventory)) {
405	    if (typeof k !== "string" || typeof v !== "number" || v < 0) return false;
406	  }
407	
408	  // equipment
409	  if (!Array.isArray(s.equipment)) return false;
410	  const validEquipKinds = new Set(["oven", "warming_shelf"]);
411	  const validEquipStatuses = new Set(["working", "failed", "degraded"]);
412	  for (const eq of s.equipment) {
413	    if (typeof eq !== "object" || eq === null) return false;
414	    if (typeof eq.id !== "string") return false;
415	    if (!validEquipKinds.has(eq.kind) || !validEquipStatuses.has(eq.status)) return false;
416	  }
417	
418	  // workers
419	  if (!Array.isArray(s.workers)) return false;
420	  const validRoles = new Set(["host", "supply_lead", "chef", "server", "expediter"]);
421	  const validLocations = new Set(["floor", "kitchen", "pass", "queue"]);
422	  for (const w of s.workers) {
423	    if (typeof w !== "object" || w === null) return false;
424	    if (typeof w.id !== "string") return false;
425	    if (!validRoles.has(w.role) || !validLocations.has(w.location)) return false;
426	    if (typeof w.load !== "number" || w.load < 0 || w.load > 1) return false;
427	  }
428	
429	  // reputation
430	  if (typeof s.reputation !== "number" || s.reputation < 0 || s.reputation > 100) return false;
431	
432	  // outcomes
433	  if (typeof s.outcomes !== "object" || s.outcomes === null) return false;
434	  const out = s.outcomes as Record<string, unknown>;
435	  const reqOutcomes = [
436	    "cash",
437	    "satisfaction",
438	    "waste",
439	    "waitTime",
440	    "completed",
441	    "safeOrders",
442	    "coordination",
443	    "correctionUptake",
444	  ];
445	  for (const key of reqOutcomes) {
446	    if (typeof out[key] !== "number") return false;
447	  }
448	
449	  // optional emergency
450	  if (s.emergency !== undefined && s.emergency !== null) {
451	    const em = s.emergency as Record<string, unknown>;
452	    if (em.kind !== "oven_failure") return false;
453	    if (typeof em.active !== "boolean" || typeof em.startedAt !== "number") return false;
454	  }
455	
456	  return true;
457	}
