import { RestaurantGame } from "./src/games/restaurant-arena/restaurant-game.js";
import { computeStateHash, canonicalJson } from "./src/games/restaurant-arena/trace.js";

const path = process.argv[2]!;
const trace = JSON.parse(await Bun.file(path).text());
const game = new RestaurantGame(trace.seed, trace.replay.variation);
const fresh = game.getInitialState();
console.log("fresh init hash", computeStateHash(fresh));
console.log("trace init hash", computeStateHash(trace.initialState));
if (canonicalJson(fresh) !== canonicalJson(trace.initialState)) {
  console.log("INITIAL STATE DIFFERS");
  console.log("fresh:", canonicalJson(fresh).slice(0, 400));
  console.log("trace:", canonicalJson(trace.initialState).slice(0, 400));
}

let i = 0;
for (const input of trace.replay.inputs) {
  const tickBefore = game.state().episode.tick;
  if (tickBefore !== input.tick) console.log(`input ${i} tick mismatch: engine ${tickBefore} vs recorded ${input.tick}`);
  if (input.kind === "step") game.step(input.action);
  else if (input.kind === "time") game.advanceTime();
  else if (input.kind === "envelope") game.stepEnvelope(input.envelope, input.telemetry);
  else if (input.kind === "controllers") game.setExternalControllers(input.roles);
  const got = computeStateHash(game.checkpointState());
  if (got !== input.stateHash) console.log(`input ${i} (${input.kind} ${input.action ?? input.envelope?.tool ?? ""}) hash mismatch: ${got} vs ${input.stateHash}`);
  if (input.restaurantStateHash) {
    const r = computeStateHash(game.state());
    if (r !== input.restaurantStateHash) console.log(`input ${i} restaurant hash mismatch`);
  }
  i++;
}
console.log("final", computeStateHash(game.checkpointState()), "expected", trace.replay.finalStateHash);
console.log("finalRestaurant", computeStateHash(game.state()), "expected", trace.replay.finalRestaurantStateHash);
console.log("terminal", JSON.stringify(game.getTerminalStatus()), "expected", JSON.stringify(trace.terminal));
console.log("events", game.getRecordedEvents().length, "recorded", trace.events.length);

