import { RestaurantGame } from "./src/games/restaurant-arena/restaurant-game.js";
import { computeStateHash } from "./src/games/restaurant-arena/trace.js";

const trace = JSON.parse(await Bun.file("contracts/fixtures/restaurant-arena-trace-v3.json").text());
const target = trace.replay.inputs[0].stateHash;
const game = new RestaurantGame(trace.seed, trace.replay.variation);
game.step("sim_start");
const cp = game.checkpointState() as Record<string, unknown>;
console.log("keys", Object.keys(cp).join(","));
console.log("full", computeStateHash(cp), "target", target);

// try removing each subset of one key
for (const key of Object.keys(cp)) {
  const copy = { ...cp };
  delete copy[key];
  if (computeStateHash(copy) === target) console.log("MATCH by dropping", key);
}
// try removing pairs
const keys = Object.keys(cp);
for (let i = 0; i < keys.length; i++) for (let j = i + 1; j < keys.length; j++) {
  const copy = { ...cp };
  delete copy[keys[i]!];
  delete copy[keys[j]!];
  if (computeStateHash(copy) === target) console.log("MATCH by dropping", keys[i], keys[j]);
}
for (let i = 0; i < keys.length; i++) for (let j = i + 1; j < keys.length; j++) for (let k = j + 1; k < keys.length; k++) {
  const copy = { ...cp };
  delete copy[keys[i]!]; delete copy[keys[j]!]; delete copy[keys[k]!];
  if (computeStateHash(copy) === target) console.log("MATCH by dropping3", keys[i], keys[j], keys[k]);
}

