1	/**
2	 * Compact Decision-and-Correction Timeline Viewer for Restaurant Arena.
3	 * Aligns with Issue #263 and docs/true-demo-day-11-day-plan-legacy.md (Sep 5).
4	 *
5	 * Presents the 4 key sequence milestones in order:
6	 *  1. Original decision (Incident trigger & Proposed worker action)
7	 *  2. Correction (Player intervention & Worker reaction)
8	 *  3. Later probe (Warming shelf decision)
9	 *  4. Outcome (Shift outcome metrics)
10	 */
11	
12	import type { RestaurantGame } from "./restaurant-game.js";
13	import type { RestaurantArenaTraceV3, TraceV3Event, TraceV3Role } from "./trace.js";
14	import type { ArenaView } from "./arena-view.js";
15	import type { Role } from "./types.js";
16	import { WARMING_SHELF_PROBE_TAG } from "./scope-probe.js";
17	
18	export type SequenceMilestone =
19	  | "original_decision"
20	  | "correction"
21	  | "later_probe"
22	  | "outcome";
23	
24	export const KEY_SEQUENCE_MILESTONES: readonly SequenceMilestone[] = [
25	  "original_decision",
26	  "correction",
27	  "later_probe",
28	  "outcome",
29	] as const;
30	
31	export type TimelineBadgeTone =
32	  | "danger"
33	  | "warning"
34	  | "info"
35	  | "success"
36	  | "neutral";
37	
38	export interface TimelineCard {
39	  readonly id: string;
40	  readonly milestone: SequenceMilestone;
41	  readonly stepIndex: number; // Recorded order, starting at 1
42	  readonly title: string;
43	  readonly role?: Role | TraceV3Role | "player" | "system" | "house";
44	  readonly tick: number;
45	  readonly badgeText: string;
46	  readonly badgeTone: TimelineBadgeTone;
47	  readonly headline: string;
48	  readonly detail: string;
49	  readonly metadata?: Record<string, string | number | boolean>;
50	}
51	
52	export interface TimelineModel {
53	  readonly cards: readonly TimelineCard[];
54	  readonly milestonesPresented: readonly SequenceMilestone[];
55	  readonly episodeId: string;
56	  readonly isComplete: boolean;
57	}
58	
59	function escapeHtml(text: string): string {
60	  return text
61	    .replace(/&/g, "&amp;")
62	    .replace(/</g, "&lt;")
63	    .replace(/>/g, "&gt;")
64	    .replace(/"/g, "&quot;")
65	    .replace(/'/g, "&#39;");
66	}
67	
68	function isTrace(obj: unknown): obj is RestaurantArenaTraceV3 {
69	  return (
70	    typeof obj === "object" &&
71	    obj !== null &&
72	    (obj as RestaurantArenaTraceV3).version === "restaurant-arena-trace/v3" &&
73	    Array.isArray((obj as RestaurantArenaTraceV3).events)
74	  );
75	}
76	
77	function isGame(obj: unknown): obj is RestaurantGame {
78	  return (
79	    typeof obj === "object" &&
80	    obj !== null &&
81	    typeof (obj as RestaurantGame).state === "function" &&
82	    typeof (obj as RestaurantGame).view === "function"
83	  );
84	}
85	
86	/** Show recorded facts only; a missing response is never a successful probe. */
87	export function buildArenaTimeline(source: RestaurantGame | RestaurantArenaTraceV3 | ArenaView): TimelineModel {
88	  const trace = isTrace(source);
89	  const game = isGame(source);
90	  const state = game ? source.state() : trace ? undefined : source;
91	  const events: Pick<TraceV3Event, "tick" | "kind" | "actorId" | "role" | "text" | "payload" | "toolResult" | "action">[] = trace
92	    ? source.events
93	    : game
94	      ? source.getRecordedEvents()
95	      : source.feed.map((entry) => ({
96	          tick: entry.tick,
97	          kind: entry.voice === "you" ? "player_correction" : entry.kind === "action" ? "action" : "message",
98	          actorId: entry.voice === "you" ? "player" : entry.voice === "house" ? "system" : entry.voice,
99	          text: entry.text,
100	        }));
101	  const cards: TimelineCard[] = events.map((event, index) => {
102	    const probe = event.payload?.probe === WARMING_SHELF_PROBE_TAG;
103	    const player = event.actorId === "player" || event.kind === "player_correction";
104	    const correction = event.kind === "player_correction";
105	    const milestone: SequenceMilestone = event.kind === "outcome" ? "outcome" : probe ? "later_probe" : correction ? "correction" : "original_decision";
106	    const failed = event.toolResult?.ok === false;
107	    return {
108	      id: `recorded-${index}`, milestone, stepIndex: index + 1,
109	      title: event.kind === "outcome" ? "Shift Outcome Metrics" : correction ? "Player Intervention" : probe ? "Warming Shelf Event" : "Recorded Event",
110	      role: player ? "player" : event.role ?? "system",
111	      tick: event.tick,
112	      badgeText: failed ? "REJECTED" : event.kind.replaceAll("_", " ").toUpperCase(),
113	      badgeTone: failed ? "danger" : player ? "info" : "neutral",
114	      headline: event.text ?? `${event.actorId ?? "system"}: ${event.action?.tool ?? event.kind}`,
115	      detail: event.toolResult?.error?.message ?? (probe && event.payload?.stage === "trigger" ? "Equipment event recorded. This alone does not establish a worker response or a passing grade." : ""),
116	    };
117	  });
118	  return {
119	    cards,
120	    milestonesPresented: KEY_SEQUENCE_MILESTONES.filter((milestone) => cards.some((card) => card.milestone === milestone)),
121	    episodeId: trace ? source.episodeId : state!.episode.id,
122	    isComplete: trace ? source.terminal.status === "completed" : state!.episode.phase === "complete",
123	  };
124	}
125	
126	/**
127	 * Render the Timeline Viewer HTML.
128	 * Includes milestone progress strip and scrollable chronological cards.
129	 * Designed to handle large traces gracefully with smooth scrolling and zero visual clipping.
130	 */
131	export function renderTimelineHtml(timeline: TimelineModel): string {
132	  const milestoneLabels: Record<SequenceMilestone, string> = {
133	    original_decision: "1. Original Decision",
134	    correction: "2. Player Correction",
135	    later_probe: "3. Later Probe",
136	    outcome: "4. Shift Outcomes",
137	  };
138	
139	  const stepsHtml = KEY_SEQUENCE_MILESTONES.map((milestone, idx) => {
140	    const isPresented = timeline.milestonesPresented.includes(milestone);
141	    return `
142	      <div class="milestone-step${isPresented ? " is-active" : ""}" data-milestone="${milestone}">
143	        <span class="milestone-dot">${idx + 1}</span>
144	        <span class="milestone-name">${escapeHtml(milestoneLabels[milestone])}</span>
145	      </div>
146	    `;
147	  }).join('<div class="milestone-connector"></div>');
148	
149	  const cardsHtml = timeline.cards
150	    .map((card) => {
151	      const toneClass = `badge-${card.badgeTone}`;
152	      return `
153	        <div class="arena-timeline-card" data-milestone="${card.milestone}" data-step="${card.stepIndex}">
154	          <div class="card-header">
155	            <span class="card-step">#${card.stepIndex}</span>
156	            <span class="card-badge ${toneClass}">${escapeHtml(card.badgeText)}</span>
157	            <span class="card-title">${escapeHtml(card.title)}</span>
158	            <span class="card-tick">Tick ${card.tick}</span>
159	          </div>
160	          <p class="card-headline">${escapeHtml(card.headline)}</p>
161	          <p class="card-detail">${escapeHtml(card.detail)}</p>
162	        </div>
163	      `;
164	    })
165	    .join("");
166	
167	  return `
168	    <div class="arena-timeline" role="region" aria-label="Shift decision and correction timeline" data-sequence="original_decision correction later_probe outcome">
169	      <div class="arena-timeline-header">
170	        <span class="arena-timeline-title">DECISION &amp; CORRECTION TIMELINE</span>
171	        <span class="arena-timeline-badge">${timeline.milestonesPresented.length} MILESTONES</span>
172	      </div>
173	      <div class="arena-timeline-milestones">
174	        ${stepsHtml}
175	      </div>
176	      <div class="arena-timeline-cards" tabindex="0" role="feed" aria-label="Chronological decision cards">
177	        ${cardsHtml}
178	      </div>
179	    </div>
180	  `;
181	}
182

