  }

  function checkTerminal(): void {
    const terminal = trace.terminal;
    if (!isRecord(terminal)) return fail("terminal", "must be an object");
    for (const key of Object.keys(terminal)) {
      if (!["status", "tick", "reason"].includes(key)) fail(`terminal.${key}`, "is not a terminal field");
    }
    if (typeof terminal.status !== "string" || !TERMINAL_STATUSES.includes(terminal.status)) {
