    if (!isRecord(event)) return fail(path, "must be an object");
    for (const key of Object.keys(event)) {
      if (!EVENT_KEYS.includes(key)) fail(`${path}.${key}`, "is not a trace event field");
    }
    checkTick(`${path}.tick`, event.tick);
    if (typeof event.kind !== "string" || !TRACE_EVENT_KINDS.includes(event.kind as TraceEventKind)) {
      fail(`${path}.kind`, `must be one of ${TRACE_EVENT_KINDS.join(", ")}`);
    }
    if (typeof event.timestamp !== "string" || !DATE_TIME_PATTERN.test(event.timestamp) || !Number.isFinite(Date.parse(event.timestamp))) {
      fail(`${path}.timestamp`, "must be an RFC 3339 date-time string");
    }
    checkStateHash(`${path}.stateHash`, event.stateHash, true);
    if (event.round !== undefined && (typeof event.round !== "number" || !Number.isInteger(event.round) || event.round < 1)) {
