    }
    if (event.actorId !== undefined) checkArenaId(`${path}.actorId`, event.actorId, false);
    if (event.requestId !== undefined) checkArenaId(`${path}.requestId`, event.requestId, false);
    if (event.checkpointId !== undefined) checkArenaId(`${path}.checkpointId`, event.checkpointId, false);
    for (const key of ["role", "targetRole"] as const) {
      const role = event[key];
      if (role !== undefined && (typeof role !== "string" || !TRACE_EVENT_ROLES.includes(role))) {
