    if (event.correctionRationale !== undefined) checkNullableString(`${path}.correctionRationale`, event.correctionRationale);
    for (const key of ["observation", "action", "outcome", "payload"] as const) {
      if (event[key] !== undefined) checkNullableObject(`${path}.${key}`, event[key]);
    }
