    if (event.toolResult !== undefined) checkToolResult(`${path}.toolResult`, event.toolResult);
  }

  function checkModel(path: string, model: unknown): void {
    if (!isRecord(model)) return fail(path, "must be an object");
    for (const key of Object.keys(model)) {
      if (!["provider", "name", "version"].includes(key)) fail(`${path}.${key}`, "is not a model field");
    }
    for (const key of ["provider", "name"] as const) {
      if (typeof model[key] !== "string" || (model[key] as string).length === 0) fail(`${path}.${key}`, "must be a non-empty string");
    }
    if (model.version !== undefined && (typeof model.version !== "string" || model.version.length === 0)) {
      fail(`${path}.version`, "must be a non-empty string");
    }
  }

  function checkSubject(path: string, subject: unknown): void {
    if (!isRecord(subject)) return fail(path, "must be an object");
    for (const key of Object.keys(subject)) {
      if (!["kind", "id"].includes(key)) fail(`${path}.${key}`, "is not a subject field");
    }
    if (typeof subject.kind !== "string" || !SUBJECT_KINDS.includes(subject.kind)) {
      fail(`${path}.kind`, `must be one of ${SUBJECT_KINDS.join(", ")}`);
    }
    checkArenaId(`${path}.id`, subject.id, true);
  }

  /**
   * The three keys a grader sorts failures on have to agree with each other:
   * a consumer filtering on `ok` and one filtering on `error` must not read
   * the same event differently.
   */
  function checkToolResult(path: string, result: unknown): void {
    if (result === null) return;
    if (!isRecord(result)) return fail(path, "must be an object or null");
    if (result.ok !== undefined && typeof result.ok !== "boolean") fail(`${path}.ok`, "must be a boolean");
    if (result.latencyMs !== undefined && (typeof result.latencyMs !== "number" || result.latencyMs < 0)) {
      fail(`${path}.latencyMs`, "must be a number >= 0");
    }
