    }
  }

  function checkDeletion(): void {
    const deletion = trace.deletion;
    if (!isRecord(deletion)) return fail("deletion", "must be an object");
    for (const key of Object.keys(deletion)) {
      if (!["requestId", "status"].includes(key)) fail(`deletion.${key}`, "is not a deletion field");
    }
    if (deletion.requestId !== null) checkArenaId("deletion.requestId", deletion.requestId, true);
    if (typeof deletion.status !== "string" || !DELETION_STATUSES.includes(deletion.status)) {
      fail("deletion.status", `must be one of ${DELETION_STATUSES.join(", ")}`);
    }
  }

  function checkReplay(): void {
    const replay = trace.replay;
    if (!isRecord(replay)) return fail("replay", "must be an object");
    for (const key of Object.keys(replay)) {
      if (!["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"].includes(key)) {
        fail(`replay.${key}`, "is not a replay field");
      }
    }
    if (typeof replay.variation !== "string" || !(replay.variation in SHIFT_PRESETS)) {
      fail("replay.variation", `must be one of ${Object.keys(SHIFT_PRESETS).join(", ")}`);
    }
    checkStateHash("replay.finalStateHash", replay.finalStateHash, true);
    if (replay.finalRestaurantStateHash !== undefined) {
      checkStateHash("replay.finalRestaurantStateHash", replay.finalRestaurantStateHash, false);
    }
    if (!Array.isArray(replay.inputs)) return fail("replay.inputs", "must be an array");
    replay.inputs.forEach((input, index) => checkInput(`replay.inputs[${index}]`, input));
  }

  function checkInput(path: string, input: unknown): void {
    if (!isRecord(input)) return fail(path, "must be an object");
    const kind = input.kind;
    if (typeof kind !== "string" || !(kind in INPUT_KEYS)) {
      return fail(`${path}.kind`, `must be one of ${Object.keys(INPUT_KEYS).join(", ")}`);
    }
    const allowed = INPUT_KEYS[kind]!;
    for (const key of Object.keys(input)) {
      if (!allowed.includes(key)) fail(`${path}.${key}`, `is not a ${kind} input field`);
    }
    checkTick(`${path}.tick`, input.tick);
    checkStateHash(`${path}.stateHash`, input.stateHash, true);
    if (input.restaurantStateHash !== undefined) checkStateHash(`${path}.restaurantStateHash`, input.restaurantStateHash, false);
    if (kind === "step" && (typeof input.action !== "string" || input.action.length === 0)) {
      fail(`${path}.action`, "must be a non-empty action id");
    }
    if (kind === "envelope" && !isActionEnvelope(input.envelope)) {
      fail(`${path}.envelope`, "must be a restaurant-arena-action/v1 envelope");
    }
    if (kind === "envelope" && input.telemetry !== undefined && !isRecord(input.telemetry)) {
      fail(`${path}.telemetry`, "must be an object");
    }
    if (kind === "controllers") {
      const roles = input.roles;
      if (!Array.isArray(roles)) fail(`${path}.roles`, "must be an array of roles");
      else {
