// ── Capture ─────────────────────────────────────────────────────────────

export interface TraceCaptureOptions {
  episodeId?: string;
  sessionId?: string;
  /** Required: live gameplay, synthetic episodes and benchmark episodes must stay distinguishable. */
  runKind: TraceV3RunKind;
  envVersion?: string;
  /**
   * The wall clock tick 0 happened at. Given one, the run's own event
   * timestamps are restamped from it (`startTime + tick * TRACE_TICK_MS`), so
   * the same shift played twice exports the same bytes — that is what makes a
   * checked-in fixture possible.
   */
  startTime?: string;
  deletion?: Partial<TraceV3Deletion>;
  /** Omit to capture the run's own recorded event journal; pass to replace it wholesale. */
  events?: TraceV3Event[];
  /**
   * Events the caller wants merged into the captured journal alongside the
   * game's own recorded events (e.g. an out-of-band player note). Each
   * caller-supplied event is stamped with the `round` its `tick` falls in, so
   * a reviewer can line it up against the worker turns around it, and the
   * merged journal stays in tick order.
   */
  additionalEvents?: TraceV3Event[];
}

/** The engine surface a capture reads. Kept narrow so a test can stand in for a game. */
type CapturableGame = Pick<
  RestaurantGame,
  "state" | "getInitialState" | "getRecordedEvents" | "getReplayRecord" | "getTerminalStatus"
> & { contract?: RestaurantGame["contract"] };

function restampEventTimestamps(events: TraceV3Event[], startTime?: string): TraceV3Event[] {
  if (startTime === undefined) return events;
  const startMs = Date.parse(startTime);
  if (!Number.isFinite(startMs)) {
    throw new TypeError(`captureArenaTrace: startTime is not a date-time: ${startTime}`);
  }
  // Spread first so the rewritten timestamp keeps its place in the key order.
  return events.map((event) => ({ ...event, timestamp: new Date(startMs + event.tick * TRACE_TICK_MS).toISOString() }));
}

