/**
 * Native replay of a restaurant-arena-trace-v3 record.
 *
 * Replay is the only thing that can tell an honest trace from a plausible
 * one. `validateArenaTraceV3` says a record is well-formed; this module
 * rebuilds the episode in this engine, from this engine's own seed, and
 * refuses the record the moment the world it produces stops matching the
 * world the trace claims.
 */

import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
import {
  TRACE_V3_VERSION,
  computeStateHash,
  type RestaurantArenaTraceV3,
} from "./trace.js";
import type { Role } from "./types.js";

/**
 * `expediter` was the v1 name for the pass worker now called `supply_lead`.
 * Only the name changed — not the worker's behavior, and not the outcome it
 * produces — so a historical trace naming the legacy roster has to keep
 * replaying. Canonicalizing both sides before hashing is what lets the
 * initial-state check stay strict about every other field.
 */
export function canonicalizeArenaInitialState(state: Record<string, unknown>): Record<string, unknown> {
  const workers = state.workers;
  if (!Array.isArray(workers)) return state;
  return {
    ...state,
    workers: workers.map((entry) => {
      if (typeof entry !== "object" || entry === null) return entry;
      const worker = { ...(entry as Record<string, unknown>) };
      if (worker.role === "expediter") worker.role = "supply_lead";
      if (worker.id === "worker-expediter" || worker.id === "expediter") worker.id = "worker-supply_lead";
      return worker;
    }),
  };
}

/**
 * Re-apply one recorded input and check the checkpoint it lands on.
 *
 * The recorded hash is compared against what this engine actually produces,
 * so a trace whose inputs were edited, dropped or reordered fails here rather
