/**
 * Export (or check) the benchmark trace fixture.
 *
 *   bun scripts/export-arena-trace.ts            # write the fixture
 *   bun scripts/export-arena-trace.ts --check    # verify the fixture on disk is current
 *
 * The fixture is the frozen example of a restaurant-arena-trace-v3 record:
 * one benchmark shift on the Dinner Rush seed, captured with a fixed start
 * time so the same shift always exports the same bytes. `--check` is the CI
 * guard — if the engine changes what the seed produces, the fixture has to be
 * regenerated deliberately rather than drifting out of date in silence.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import { exportTraceJson, validateArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

const ROOT = join(import.meta.dir, "..");
const FIXTURE_PATH = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

/** Fixed so the export is reproducible: same seed, same shift, same bytes. */
const FIXTURE_SEED = 218220;
const FIXTURE_VARIATION = "dinner-rush";
const FIXTURE_EPISODE_ID = "dinner-rush-benchmark-218220";
const FIXTURE_START_TIME = "2026-09-05T18:00:00.000Z";
/** Ticks before the manager's safety correction lands. */
const TICKS_BEFORE_CORRECTION = 10;

function usage(): never {
  console.error("Usage: bun scripts/export-arena-trace.ts [--check]");
  process.exit(2);
}

/**
 * The benchmark shift: open the doors, run into the oven failure and the
 * allergy ticket, correct the pass, then let the rest of the service play out.
 */
function captureFixtureTrace() {
  const game = new RestaurantGame(FIXTURE_SEED, FIXTURE_VARIATION);
  game.step("sim_start");
  for (let i = 0; i < TICKS_BEFORE_CORRECTION; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game.captureTrace({
    runKind: "benchmark",
    episodeId: FIXTURE_EPISODE_ID,
    startTime: FIXTURE_START_TIME,
  });
}

const check = process.argv.slice(2).includes("--check");
if (process.argv.slice(2).some((argument) => argument !== "--check")) usage();

const trace = captureFixtureTrace();

// A fixture nobody can validate or replay is not evidence of anything, so the
// export refuses to write one.
const validation = validateArenaTraceV3(trace);
if (!validation.valid) {
  console.error(`Captured trace is not a valid restaurant-arena-trace-v3 record:\n${validation.errors.join("\n")}`);
  process.exit(1);
}
replayArenaTrace(trace);

const serialized = `${exportTraceJson(trace)}\n`;
const shown = relative(process.cwd(), FIXTURE_PATH);

if (check) {
  let onDisk: string;
  try {
    onDisk = readFileSync(FIXTURE_PATH, "utf8");
  } catch {
    console.error(`Fixture is missing: ${shown}. Run: bun scripts/export-arena-trace.ts`);
    process.exit(1);
  }
  if (onDisk !== serialized) {
    console.error(`Fixture is stale: ${shown} no longer matches a fresh capture. Run: bun scripts/export-arena-trace.ts`);
    process.exit(1);
  }
  console.log(`Fixture is current: ${shown}`);
} else {
  writeFileSync(FIXTURE_PATH, serialized);
  console.log(`Wrote ${shown} (${trace.events.length} events, ${trace.replay.inputs.length} replay inputs)`);
}

