/**
 * Natively replay a trace file from disk and say whether it holds up.
 *
 *   bun scripts/replay-arena-trace.ts <trace.json|trace.jsonl>
 *
 * Both export shapes are accepted: the JSON document from `exportTraceJson`
 * and the newline-delimited stream from `exportTraceJsonl` (header line, then
 * one event per line). The file is validated field by field and then replayed
 * in this engine from its own seed; a tampered, truncated or stale trace fails
 * here instead of being graded as a real run.
 */

import { readFileSync } from "node:fs";
import { validateArenaTraceV3, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

/** JSONL is a header line plus one event per line; `{...header, events}` is the trace. */
function parseJsonl(text: string): unknown {
  const [header, ...events] = text
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as unknown);
  if (header === undefined) throw new Error("trace file is empty");
  return { ...(header as Record<string, unknown>), events };
}

function parseTraceFile(path: string): unknown {
  const text = readFileSync(path, "utf8");
  // Extension first, content as the fallback: a JSONL export renamed .json is
  // still the same trace, and vice versa.
  if (path.endsWith(".jsonl")) {
    try {
      return parseJsonl(text);
    } catch {
      return JSON.parse(text) as unknown;
    }
  }
  try {
    return JSON.parse(text) as unknown;
  } catch (error) {
    if (text.trim().includes("\n")) return parseJsonl(text);
    throw error;
  }
}

const path = process.argv[2];
if (!path || path.startsWith("-")) usage();

try {
  const parsed = parseTraceFile(path);
  const validation = validateArenaTraceV3(parsed);
  if (!validation.valid) {
    console.error(`Trace is not a valid restaurant-arena-trace-v3 record: ${path}`);
    for (const error of validation.errors) console.error(`  ${error}`);
    process.exit(1);
  }
  const trace = parsed as RestaurantArenaTraceV3;
  const game = replayArenaTrace(trace);
  const terminal = game.getTerminalStatus();
  console.log(
    `Native replay passed: ${path} (${trace.replay.inputs.length} inputs, ${trace.events.length} events, tick ${terminal.tick}, ${terminal.status})`,
  );
} catch (error) {
  console.error(`Native replay failed: ${path}`);
  console.error(`  ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

