import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "./restaurant-game.js";
import {
  ARENA_ENV_VERSION,
  TRACE_V3_CONTRACT_VERSION,
  TRACE_V3_VERSION,
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

/** A short Dinner Rush shift with a correction in it, played the same way every time. */
function playedShift(ticks = 6): RestaurantGame {
  const game = new RestaurantGame(218220, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < ticks; i++) game.step("tick");
  return game;
}

function completedShift(): RestaurantGame {
  const game = playedShift(8);
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game;
}

function note(tick: number): TraceV3Event {
  return {
    tick,
    kind: "message",
    timestamp: new Date(Date.UTC(2026, 0, 1, 0, 0, tick)).toISOString(),
    stateHash: `sha256:${"a".repeat(64)}`,
    actorId: "player",
    text: `out-of-band note at tick ${tick}`,
  };
}

describe("captureArenaTrace / RestaurantGame#captureTrace", () => {
  it("captures the tick-0 world, the journal and the ordered replay inputs", () => {
    const game = completedShift();
    const trace = game.captureTrace({ runKind: "benchmark" });

    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
    expect(trace.version).toBe(TRACE_V3_VERSION);
    expect(trace.contractVersion).toBe(TRACE_V3_CONTRACT_VERSION);
    expect(trace.envVersion).toBe(ARENA_ENV_VERSION);
    expect(trace.runKind).toBe("benchmark");
    expect(trace.seed).toBe(218220);
    expect(trace.episodeId).toBe(game.state().episode.id);
    expect(trace.sessionId).toBeUndefined();
    // The world before the first tick moved anything, not the world at capture.
    expect(trace.initialState).toEqual(game.getInitialState());
    expect((trace.initialState.episode as { tick: number }).tick).toBe(0);
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(trace.replay.inputs.length).toBeGreaterThan(0);
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });
  });

  it("is the same record whether captured through the instance method or the standalone helper", () => {
    const game = completedShift();
    const options = { runKind: "live", sessionId: "session-42", startTime: "2026-09-05T18:00:00.000Z" } as const;
    expect(game.captureTrace(options)).toEqual(captureArenaTrace(game, options));
  });

  it("refuses to capture a run that does not say what kind of run it was", () => {
    const game = playedShift();
    // Live gameplay, synthetic episodes and benchmark episodes have to stay
    // distinguishable on receipt, so runKind is not optional.
    expect(() => game.captureTrace({} as never)).toThrow(/runKind/);
    expect(() => captureArenaTrace(game, { runKind: "rehearsal" } as never)).toThrow(/runKind/);
  });

  it("carries the whole terminal record, not just the status", () => {
    const abandoned = playedShift(3);
    abandoned.markAbandoned("user_quit");
    expect(abandoned.captureTrace({ runKind: "live" }).terminal).toEqual({
      status: "abandoned",
      tick: 3,
      reason: "user_quit",
    });
    expect(completedShift().captureTrace({ runKind: "live" }).terminal).toEqual({
      status: "completed",
      tick: 24,
      reason: "episode_complete",
    });
  });

  it("names the session when it is given one, without touching the episode id", () => {
    const trace = playedShift().captureTrace({ runKind: "live", sessionId: "game-abc123" });
    expect(trace.sessionId).toBe("game-abc123");
    expect(trace.episodeId).toBe("dinner-rush-001");
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("takes an explicit episode id and env version", () => {
    const trace = playedShift().captureTrace({
      runKind: "synthetic",
      episodeId: "dinner-rush-benchmark-218220",
      envVersion: "9.9.9",
    });
    expect(trace.episodeId).toBe("dinner-rush-benchmark-218220");
    expect(trace.envVersion).toBe("9.9.9");
  });

  it("stamps merged caller events with the round their tick falls in", () => {
    const game = completedShift();
    const journal = game.getRecordedEvents();
    // Round r advances ticks 2r-1 and 2r; tick 0 is the opening envelope.
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note(0), note(3), note(4), note(15)] });

    const merged = trace.events.filter((event) => event.text?.startsWith("out-of-band"));
    expect(merged.map((event) => [event.tick, event.round])).toEqual([[0, 1], [3, 2], [4, 2], [15, 8]]);
    // The run's own journal survives the merge, in order, and the result stays
    // chronological so a reviewer reads the shift as it happened.
    expect(trace.events.filter((event) => !event.text?.startsWith("out-of-band"))).toEqual(journal);
    expect(trace.events.length).toBe(journal.length + 4);
    expect(trace.events.map((event) => event.tick)).toEqual([...trace.events.map((event) => event.tick)].sort((a, b) => a - b));
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("replaces the journal wholesale when the caller supplies its own events", () => {
    const game = completedShift();
    const trace = game.captureTrace({ runKind: "synthetic", events: [note(2)] });
    expect(trace.events).toEqual([note(2)]);
  });

  it("defaults the deletion record to retained and takes a partial override", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "live", deletion: { status: "requested" } }).deletion).toEqual({
      requestId: null,
      status: "requested",
    });
    expect(game.captureTrace({ runKind: "live", deletion: { requestId: "del-7", status: "deleted" } }).deletion).toEqual({
      requestId: "del-7",
      status: "deleted",
    });
  });

  it("restamps the run's own events from a fixed start time, so the same shift exports the same bytes", () => {
    const first = exportTraceJson(completedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" }));
    const second = exportTraceJson(completedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" }));
    expect(first).toBe(second);

    const trace = JSON.parse(first) as RestaurantArenaTraceV3;
    for (const event of trace.events) {
      expect(event.timestamp).toBe(new Date(Date.parse("2026-09-05T18:00:00.000Z") + event.tick * 3000).toISOString());
    }
    // A caller-supplied event keeps the timestamp the caller gave it.
    const merged = completedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z", additionalEvents: [note(4)] });
    expect(merged.events.find((event) => event.text?.startsWith("out-of-band"))?.timestamp).toBe(note(4).timestamp);
  });

  it("rejects a start time that is not a date-time", () => {
    expect(() => playedShift().captureTrace({ runKind: "live", startTime: "half past six" })).toThrow(/startTime/);
  });
});

describe("exportTraceJson / exportTraceJsonl", () => {
  it("round-trips the whole record as JSON", () => {
    const trace = completedShift().captureTrace({ runKind: "live" });
    const parsed = JSON.parse(exportTraceJson(trace)) as RestaurantArenaTraceV3;
    expect(parsed).toEqual(trace);
    expect(validateArenaTraceV3(parsed)).toEqual({ valid: true, errors: [] });
  });

  it("streams a header line plus one line per event that reassembles the trace", () => {
    const trace = completedShift().captureTrace({ runKind: "live" });
    const lines = exportTraceJsonl(trace).split("\n");
    expect(lines.length).toBe(trace.events.length + 1);

    const header = JSON.parse(lines[0]!) as Record<string, unknown>;
    // The header carries everything except the journal, so `{...header, events}`
    // is the trace again — that is what the schema validator consumes.
    expect(header.events).toBeUndefined();
    const events = lines.slice(1).map((line) => JSON.parse(line) as TraceV3Event);
    expect({ ...header, events }).toEqual(trace);
    for (const event of events) expect(event.stateHash).toMatch(/^sha256:[0-9a-f]{64}$/);
  });
});

describe("validateArenaTraceV3", () => {
  const valid = completedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });

  function tampered(mutate: (trace: RestaurantArenaTraceV3) => void): RestaurantArenaTraceV3 {
    const copy = structuredClone(valid);
    mutate(copy);
    return copy;
  }

  it("accepts the checked-in benchmark fixture", () => {
    const fixture = JSON.parse(
      readFileSync(join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json"), "utf8"),
    ) as RestaurantArenaTraceV3;
    expect(validateArenaTraceV3(fixture)).toEqual({ valid: true, errors: [] });
  });

  it("accepts a historical trace that still names the legacy expediter roster", () => {
    const legacy = tampered((trace) => {
      for (const worker of trace.initialState.workers as { id: string; role: string }[]) {
        if (worker.role === "supply_lead") {
          worker.role = "expediter";
          worker.id = "worker-expediter";
        }
      }
      trace.events[1] = { ...trace.events[1]!, role: "expediter", targetRole: "expediter" };
    });
    expect(validateArenaTraceV3(legacy)).toEqual({ valid: true, errors: [] });
  });

  it("rejects anything that is not a JSON object", () => {
    for (const value of [null, undefined, 7, "trace", [valid]]) {
      expect(validateArenaTraceV3(value).valid).toBe(false);
    }
  });

  it("reports every required field that is missing", () => {
    for (const field of [
      "version", "episodeId", "seed", "envVersion", "contractVersion",
      "runKind", "initialState", "events", "deletion", "replay", "terminal",
    ] as const) {
      const result = validateArenaTraceV3(tampered((trace) => delete (trace as Record<string, unknown>)[field]));
      expect(result.valid).toBe(false);
      expect(result.errors.some((error) => error.startsWith(field))).toBe(true);
    }
  });

  it("rejects malformed fields one by one, naming the field", () => {
    const cases: [string, (trace: RestaurantArenaTraceV3) => void][] = [
      ["version", (trace) => void ((trace as { version: string }).version = "restaurant-arena-trace/v2")],
      ["contractVersion", (trace) => void ((trace as { contractVersion: string }).contractVersion = "restaurant-arena/v2")],
      ["episodeId", (trace) => void (trace.episodeId = "not a valid id!")],
      ["sessionId", (trace) => void (trace.sessionId = "")],
      ["seed", (trace) => void ((trace as { seed: unknown }).seed = -1)],
      ["seed", (trace) => void ((trace as { seed: unknown }).seed = 1.5)],
      ["envVersion", (trace) => void (trace.envVersion = "")],
      ["runKind", (trace) => void ((trace as { runKind: string }).runKind = "practice")],
      ["initialState", (trace) => void ((trace.initialState as { version: string }).version = "restaurant-arena/v0")],
      ["initialState", (trace) => void ((trace.initialState as { workers: unknown }).workers = "four")],
      ["events", (trace) => void ((trace as { events: unknown }).events = {})],
      ["events[0].kind", (trace) => void ((trace.events[0] as { kind: string }).kind = "gossip")],
      ["events[0].tick", (trace) => void ((trace.events[0] as { tick: unknown }).tick = -1)],
      ["events[0].timestamp", (trace) => void (trace.events[0]!.timestamp = "yesterday")],
      ["events[0].stateHash", (trace) => void (trace.events[0]!.stateHash = "sha256:nope")],
      ["events[0].round", (trace) => void (trace.events[0]!.round = 0)],
      ["events[0].role", (trace) => void ((trace.events[0] as { role: string }).role = "sommelier")],
      ["events[0].actorId", (trace) => void (trace.events[0]!.actorId = "worker chef")],
      ["events[0].idempotencyKey", (trace) => void (trace.events[0]!.idempotencyKey = "!nope")],
      ["events[0].model.provider", (trace) => void (trace.events[0]!.model = { provider: "", name: "opus" })],
      ["events[0].observation", (trace) => void ((trace.events[0] as { observation: unknown }).observation = "text")],
      ["events[0].correctionCategory", (trace) => void ((trace.events[0] as { correctionCategory: string }).correctionCategory = "vibes")],
      ["events[0].subject.kind", (trace) => void ((trace.events[0] as { subject: unknown }).subject = { kind: "table", id: "table-1" })],
      ["events[0].garnish", (trace) => void ((trace.events[0] as Record<string, unknown>).garnish = "extra")],
      // A failed call has to carry the error a grader sorts on, and an error
      // body has to say the call failed: the two views cannot disagree.
      ["events[0].toolResult.error", (trace) => void (trace.events[0]!.toolResult = { ok: false })],
      ["events[0].toolResult.ok", (trace) => void (trace.events[0]!.toolResult = { ok: true, error: { code: "x", message: "y" } })],
      ["events[0].toolResult.error.code", (trace) => void (trace.events[0]!.toolResult = { ok: false, error: { code: "", message: "y" } })],
      ["events[0].toolResult.latencyMs", (trace) => void (trace.events[0]!.toolResult = { ok: true, latencyMs: -3 })],
      ["deletion.status", (trace) => void ((trace.deletion as { status: string }).status = "shredded")],
      ["deletion.requestId", (trace) => void (trace.deletion.requestId = "a totally invalid id")],
      ["deletion.forever", (trace) => void ((trace.deletion as unknown as Record<string, unknown>).forever = true)],
      ["replay.variation", (trace) => void ((trace.replay as { variation: string }).variation = "sunday-brunch")],
      ["replay.finalStateHash", (trace) => void (trace.replay.finalStateHash = "deadbeef")],
      ["replay.finalRestaurantStateHash", (trace) => void (trace.replay.finalRestaurantStateHash = "sha256:XYZ")],
      ["replay.inputs", (trace) => void ((trace.replay as { inputs: unknown }).inputs = "26 steps")],
      ["replay.inputs[0].kind", (trace) => void ((trace.replay.inputs[0] as { kind: string }).kind = "teleport")],
      ["replay.inputs[0].stateHash", (trace) => void (trace.replay.inputs[0]!.stateHash = "sha256:")],
      ["replay.inputs[0].action", (trace) => void ((trace.replay.inputs[0] as { action: unknown }).action = "")],
      ["replay.inputs[0].tick", (trace) => void ((trace.replay.inputs[0] as { tick: unknown }).tick = "0")],
      ["replay.inputs[0].envelope", (trace) => void ((trace.replay.inputs as unknown[])[0] = { kind: "envelope", tick: 0, stateHash: trace.replay.finalStateHash, envelope: { tool: "prepare" } })],
      ["replay.inputs[0].roles", (trace) => void ((trace.replay.inputs as unknown[])[0] = { kind: "controllers", tick: 0, stateHash: trace.replay.finalStateHash, roles: ["chef", "chef"] })],
      ["replay.inputs[0].note", (trace) => void ((trace.replay.inputs[0] as unknown as Record<string, unknown>).note = "hand-edited")],
      ["terminal.status", (trace) => void ((trace.terminal as { status: string }).status = "cancelled")],
      ["terminal.tick", (trace) => void ((trace.terminal as { tick: unknown }).tick = -4)],
      ["terminal.reason", (trace) => void ((trace.terminal as { reason: unknown }).reason = 7)],
      ["terminal.reason", (trace) => void delete (trace.terminal as { reason?: unknown }).reason],
      ["grade", (trace) => void ((trace as unknown as Record<string, unknown>).grade = "A")],
    ];

    for (const [field, mutate] of cases) {
