1	/**
2	 * Native replay of a restaurant-arena-trace-v3 record.
3	 *
4	 * Replay is the only thing that can tell an honest trace from a plausible
5	 * one. `validateArenaTraceV3` says a record is well-formed; this module
6	 * rebuilds the episode in this engine, from this engine's own seed, and
7	 * refuses the record the moment the world it produces stops matching the
8	 * world the trace claims.
9	 */
10	
11	import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
12	import {
13	  TRACE_V3_VERSION,
14	  computeStateHash,
15	  type RestaurantArenaTraceV3,
16	} from "./trace.js";
17	
18	/**
19	 * `expediter` was the v1 name for the pass worker now called `supply_lead`.
20	 * Only the name changed — not the worker's behavior, and not the outcome it
21	 * produces — so a historical trace naming the legacy roster has to keep
22	 * replaying. Canonicalizing both sides before hashing is what lets the
23	 * initial-state check stay strict about every other field.
24	 */
25	export function canonicalizeArenaInitialState(state: Record<string, unknown>): Record<string, unknown> {
26	  const workers = state.workers;
