/**
 * Native replay of a restaurant-arena-trace-v3 record.
 *
 * Replay is the only thing that can tell an honest trace from a plausible
 * one. `validateArenaTraceV3` says a record is well-formed; this module
 * rebuilds the episode in this engine, from this engine's own seed, and
 * refuses the record the moment the world it produces stops matching the
 * world the trace claims.
 */

import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
import {
  TRACE_V3_VERSION,
  computeStateHash,
  type RestaurantArenaTraceV3,
} from "./trace.js";

/**
 * `expediter` was the v1 name for the pass worker now called `supply_lead`.
 * Only the name changed — not the worker's behavior, and not the outcome it
 * produces — so a historical trace naming the legacy roster has to keep
 * replaying. Canonicalizing both sides before hashing is what lets the
 * initial-state check stay strict about every other field.
 */
export function canonicalizeArenaInitialState(state: Record<string, unknown>): Record<string, unknown> {
  const workers = state.workers;
  if (!Array.isArray(workers)) return state;
  return {
    ...state,
    workers: workers.map((entry) => {
      if (typeof entry !== "object" || entry === null) return entry;
      const worker = { ...(entry as Record<string, unknown>) };
      if (worker.role === "expediter") worker.role = "supply_lead";
      if (worker.id === "worker-expediter" || worker.id === "expediter") worker.id = "worker-supply_lead";
      return worker;
    }),
  };
}

/**
 * Re-apply one recorded input and check the checkpoint it lands on.
 *
 * The recorded hash is compared against what this engine actually produces,
 * so a trace whose inputs were edited, dropped or reordered fails here rather
 * than reading as a clean run.
 */
export function applyArenaReplayInput(
  game: RestaurantGame,
  input: ArenaInputRecord,
  index: number,
): RestaurantGame {
  const label = `replay.inputs[${index}] (${input?.kind})`;
  if (input === null || typeof input !== "object") throw new Error(`${label}: not a replay input`);
  const tick = game.state().episode.tick;
  if (input.tick !== tick) {
    throw new Error(`${label} was recorded at tick ${input.tick}, but replay is at tick ${tick}`);
  }

  switch (input.kind) {
    case "step":
      game.step(input.action as RestaurantGameAction);
      break;
    case "time":
      game.advanceTime();
      break;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      break;
    case "controllers":
      // A legacy `expediter` in a recorded roster is canonicalized by the
      // engine itself, the same way it was on the way in.
      game.setExternalControllers(input.roles);
      break;
    default:
      throw new Error(`${label}: unknown replay input kind`);
  }

  const stateHash = computeStateHash(game.checkpointState());
  if (stateHash !== input.stateHash) {
    throw new Error(`checkpoint mismatch at ${label}: replay produced ${stateHash}, the trace records ${input.stateHash}`);
  }
  // Optional, and only on traces exported since cross-engine parity: the
  // published RestaurantState alone, without the runtime-only replay state.
  if (input.restaurantStateHash !== undefined) {
    const restaurantStateHash = computeStateHash(game.state());
    if (restaurantStateHash !== input.restaurantStateHash) {
      throw new Error(`state mismatch at ${label}: replay produced ${restaurantStateHash}, the trace records ${input.restaurantStateHash}`);
    }
  }
  return game;
}

/**
 * Rebuild the episode a trace records and return the live game itself, so a
 * caller can go on to ask it anything — `.checkpointState()`, `.state()`,
 * `.getTerminalStatus()`.
 *
 * Replay starts from a freshly constructed game for `trace.seed` and
 * `trace.replay.variation`, never from `trace.initialState` taken on faith:
 * the recorded tick-0 world is *checked* against the one this engine's seed
 * produces before any input is applied. That is a separate claim from the
 * checkpoint hashes, and it is the one that catches an initial state edited in
 * a field no schema rule covers — `cash`, say — while every field still parses.
 *
 * Throws on the first disagreement: initial state, any checkpoint hash, the
 * final state hash, or any part of the recorded terminal record (status, tick
 * and reason all have to match what replay itself reaches).
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  if (typeof trace !== "object" || trace === null) {
    throw new TypeError("replayArenaTrace: expected a restaurant-arena-trace/v3 record");
  }
  if (trace.version !== TRACE_V3_VERSION) {
    throw new Error(`replayArenaTrace: unsupported trace version ${JSON.stringify(trace.version)}; expected ${TRACE_V3_VERSION}`);
  }
  const replay = trace.replay;
  if (typeof replay !== "object" || replay === null || !Array.isArray(replay.inputs)) {
    throw new Error("replayArenaTrace: trace.replay.inputs is missing; nothing to replay");
  }
  if (typeof trace.initialState !== "object" || trace.initialState === null) {
    throw new Error("replayArenaTrace: trace.initialState is missing; the episode cannot be replayed");
  }

  const game = new RestaurantGame(trace.seed, replay.variation);
  const engineInitialHash = computeStateHash(canonicalizeArenaInitialState(game.getInitialState()));
  const tracedInitialHash = computeStateHash(canonicalizeArenaInitialState(trace.initialState));
  if (engineInitialHash !== tracedInitialHash) {
    throw new Error(
      `initial state mismatch: seed ${trace.seed} on ${replay.variation} produces ${engineInitialHash}, the trace records ${tracedInitialHash}`,
    );
  }

  replay.inputs.forEach((input, index) => applyArenaReplayInput(game, input, index));

  const finalStateHash = computeStateHash(game.checkpointState());
  if (finalStateHash !== replay.finalStateHash) {
    throw new Error(`final state hash mismatch: replay produced ${finalStateHash}, the trace records ${replay.finalStateHash}`);
  }
  if (replay.finalRestaurantStateHash !== undefined) {
    const finalRestaurantStateHash = computeStateHash(game.state());
    if (finalRestaurantStateHash !== replay.finalRestaurantStateHash) {
      throw new Error(
        `final restaurant state hash mismatch: replay produced ${finalRestaurantStateHash}, the trace records ${replay.finalRestaurantStateHash}`,
      );
    }
  }

  // The whole terminal record, not just the status: a trace whose status and
  // tick are right but whose reason was rewritten is exactly as wrong.
  const terminal = game.getTerminalStatus();
  const recorded = trace.terminal as Partial<typeof terminal> | undefined;
  if (!recorded || terminal.status !== recorded.status || terminal.tick !== recorded.tick || terminal.reason !== recorded.reason) {
    throw new Error(`terminal mismatch: replay reached ${JSON.stringify(terminal)}, the trace records ${JSON.stringify(trace.terminal)}`);
  }

  return game;
}

