137	    throw new Error(`final state hash mismatch: replay produced ${finalStateHash}, the trace records ${replay.finalStateHash}`);
138	  }
139	  if (replay.finalRestaurantStateHash !== undefined) {
140	    const finalRestaurantStateHash = computeStateHash(game.state());
141	    if (finalRestaurantStateHash !== replay.finalRestaurantStateHash) {
142	      throw new Error(
143	        `final restaurant state hash mismatch: replay produced ${finalRestaurantStateHash}, the trace records ${replay.finalRestaurantStateHash}`,
144	      );
145	    }
146	  }
147	
148	  // The whole terminal record, not just the status: a trace whose status and
149	  // tick are right but whose reason was rewritten is exactly as wrong.
150	  const terminal = game.getTerminalStatus();
151	  const recorded = trace.terminal as Partial<typeof terminal> | undefined;
152	  if (!recorded || terminal.status !== recorded.status || terminal.tick !== recorded.tick || terminal.reason !== recorded.reason) {
153	    throw new Error(`terminal mismatch: replay reached ${JSON.stringify(terminal)}, the trace records ${JSON.stringify(trace.terminal)}`);
154	  }
155	
156	  return game;
157	}
158

