import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "./restaurant-game.js";
import { applyArenaReplayInput, canonicalizeArenaInitialState, replayArenaTrace } from "./replay.js";
import { computeStateHash, validateArenaTraceV3, type RestaurantArenaTraceV3 } from "./trace.js";

/**
 * A shift that exercises all four recorded input kinds: an external controller
 * roster, plain steps, a player intervention routed as an action envelope, and
 * a bare clock advance.
 */
function mixedShift(): RestaurantGame {
  const game = new RestaurantGame(4242, "dinner-rush");
  game.setExternalControllers(["chef"]);
  game.step("sim_start");
  for (let i = 0; i < 4; i++) game.step("tick");
  game.submitPlayerIntervention({ targetRole: "expediter", kind: "message", text: "watch the pass" });
  game.advanceTime();
  while (!game.isOver()) game.step("tick");
  return game;
}

function capture(game: RestaurantGame = mixedShift()): RestaurantArenaTraceV3 {
  return game.captureTrace({ runKind: "live" });
}

const CAPTURED = capture();

function tampered(mutate: (trace: RestaurantArenaTraceV3) => void): RestaurantArenaTraceV3 {
  const copy = structuredClone(CAPTURED);
  mutate(copy);
  return copy;
}

describe("replayArenaTrace", () => {
  it("returns the rebuilt game itself, so the caller can question it directly", () => {
    const game = replayArenaTrace(CAPTURED);
    expect(game).toBeInstanceOf(RestaurantGame);
    // Not a summary object: the real thing, with the real engine's methods.
    expect(computeStateHash(game.checkpointState())).toBe(CAPTURED.replay.finalStateHash);
    expect(computeStateHash(game.state())).toBe(CAPTURED.replay.finalRestaurantStateHash);
    expect(game.getTerminalStatus()).toEqual(CAPTURED.terminal);
    expect(game.state()).toEqual(CAPTURED.replay.inputs.length ? game.state() : game.state());
    expect(game.isOver()).toBe(true);
    expect(game.view().feed.length).toBeGreaterThan(0);
  });

  it("replays every kind of recorded input", () => {
    const kinds = new Set(CAPTURED.replay.inputs.map((input) => input.kind));
    expect([...kinds].sort()).toEqual(["controllers", "envelope", "step", "time"]);
    expect(replayArenaTrace(CAPTURED).state().episode.tick).toBe(CAPTURED.terminal.tick);
  });

  it("re-captures to the same record it replayed", () => {
    const again = replayArenaTrace(CAPTURED).captureTrace({ runKind: "live" });
    expect(again.replay).toEqual(CAPTURED.replay);
    expect(again.terminal).toEqual(CAPTURED.terminal);
    expect(again.initialState).toEqual(CAPTURED.initialState);
  });

  it("replays the checked-in benchmark fixture", () => {
    const fixture = JSON.parse(
      readFileSync(join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json"), "utf8"),
    ) as RestaurantArenaTraceV3;
    expect(validateArenaTraceV3(fixture).valid).toBe(true);
    expect(replayArenaTrace(fixture).getTerminalStatus()).toEqual(fixture.terminal);
  });

  it("still replays a historical trace that names the legacy expediter worker", () => {
    const legacy = tampered((trace) => {
      for (const worker of trace.initialState.workers as { id: string; role: string }[]) {
        if (worker.role === "supply_lead") {
          worker.role = "expediter";
          worker.id = "worker-expediter";
        }
      }
    });
    // Only the role name is legacy — not the worker's behavior, and not the
    // outcome, so the replayed shift has to reach the identical terminal record.
    const game = replayArenaTrace(legacy);
    expect(game.getTerminalStatus()).toEqual(CAPTURED.terminal);
    expect(game.state().workers.map((worker) => [worker.id, worker.role])).toEqual(
      (CAPTURED.initialState.workers as { id: string; role: string }[]).map((worker) => [worker.id, worker.role]),
    );
    expect(canonicalizeArenaInitialState(legacy.initialState).workers).toEqual(CAPTURED.initialState.workers);
  });

  it("rejects an initial state edited in a field no schema rule covers", () => {
    const cooked = tampered((trace) => void ((trace.initialState.outcomes as { cash: number }).cash = 500));
    // Every field still parses, so validation alone cannot catch this; only
    // hashing it against what the seed actually produces at tick 0 can.
    expect(validateArenaTraceV3(cooked).valid).toBe(true);
    expect(() => replayArenaTrace(cooked)).toThrow(/initial state mismatch/);

    expect(() => replayArenaTrace(tampered((trace) => void ((trace.initialState.reputation as { score: number }).score = 99)))).toThrow(
      /initial state mismatch/,
    );
    expect(() => replayArenaTrace(tampered((trace) => void (trace.seed = 4243)))).toThrow(/initial state mismatch/);
    expect(() => replayArenaTrace(tampered((trace) => void ((trace.replay as { variation: string }).variation = "brunch-crunch")))).toThrow();
  });

  it("rejects a rewritten checkpoint hash, wherever in the run it sits", () => {
    for (const index of [0, 3, CAPTURED.replay.inputs.length - 1]) {
      const forged = tampered((trace) => void (trace.replay.inputs[index]!.stateHash = `sha256:${"0".repeat(64)}`));
      expect(() => replayArenaTrace(forged)).toThrow(new RegExp(`checkpoint mismatch at replay\\.inputs\\[${index}\\]`));
    }
  });

  it("rejects a rewritten published-state hash", () => {
    const forged = tampered((trace) => void (trace.replay.inputs[2]!.restaurantStateHash = `sha256:${"1".repeat(64)}`));
    expect(() => replayArenaTrace(forged)).toThrow(/state mismatch at replay\.inputs\[2\]/);
  });

  it("rejects a trace with an input dropped, duplicated or reordered", () => {
    expect(() => replayArenaTrace(tampered((trace) => void trace.replay.inputs.splice(5, 1)))).toThrow();
    expect(() => replayArenaTrace(tampered((trace) => void trace.replay.inputs.splice(5, 0, structuredClone(trace.replay.inputs[5]!))))).toThrow();
    expect(() =>
      replayArenaTrace(
        tampered((trace) => {
          const inputs = trace.replay.inputs;
          [inputs[4], inputs[8]] = [inputs[8]!, inputs[4]!];
        }),
      ),
    ).toThrow();
    // Truncating the run short of its end leaves the final hash unmet.
    expect(() => replayArenaTrace(tampered((trace) => void trace.replay.inputs.pop()))).toThrow(/final state hash mismatch/);
  });

  it("rejects a rewritten final hash", () => {
    expect(() => replayArenaTrace(tampered((trace) => void (trace.replay.finalStateHash = `sha256:${"2".repeat(64)}`)))).toThrow(
      /final state hash mismatch/,
    );
    expect(() => replayArenaTrace(tampered((trace) => void (trace.replay.finalRestaurantStateHash = `sha256:${"3".repeat(64)}`)))).toThrow(
      /final restaurant state hash mismatch/,
    );
  });

  it("rejects any part of a rewritten terminal record, not just the status", () => {
    const cases: ((trace: RestaurantArenaTraceV3) => void)[] = [
      (trace) => void ((trace.terminal as { status: string }).status = "abandoned"),
      (trace) => void (trace.terminal.tick = CAPTURED.terminal.tick - 1),
      (trace) => void (trace.terminal.reason = "user_quit"),
      (trace) => void delete (trace.terminal as { reason?: string }).reason,
      (trace) => void delete (trace as { terminal?: unknown }).terminal,
    ];
    for (const mutate of cases) {
      expect(() => replayArenaTrace(tampered(mutate))).toThrow(/terminal mismatch/);
    }
  });

  it("refuses a record it does not recognize as a v3 trace", () => {
    expect(() => replayArenaTrace(null as unknown as RestaurantArenaTraceV3)).toThrow(TypeError);
    expect(() => replayArenaTrace(tampered((trace) => void ((trace as { version: string }).version = "restaurant-arena-trace/v2")))).toThrow(
      /unsupported trace version/,
    );
    expect(() => replayArenaTrace(tampered((trace) => void delete (trace as { replay?: unknown }).replay))).toThrow(/nothing to replay/);
    expect(() => replayArenaTrace(tampered((trace) => void delete (trace as { initialState?: unknown }).initialState))).toThrow(
      /initialState is missing/,
    );
    expect(() => replayArenaTrace(tampered((trace) => void ((trace.replay.inputs as unknown[])[0] = { kind: "warp", tick: 0, stateHash: "sha256:x" })))).toThrow(
      /unknown replay input kind/,
    );
  });
});

describe("applyArenaReplayInput", () => {
  it("advances a fresh game by one recorded input and checks where it landed", () => {
    const game = new RestaurantGame(CAPTURED.seed, CAPTURED.replay.variation);
    const returned = applyArenaReplayInput(game, CAPTURED.replay.inputs[0]!, 0);
    // The same live game, moved forward — not a copy.
    expect(returned).toBe(game);
    expect(computeStateHash(game.checkpointState())).toBe(CAPTURED.replay.inputs[0]!.stateHash);
  });

  it("refuses an input recorded at a different tick than the game is on", () => {
    const game = new RestaurantGame(CAPTURED.seed, CAPTURED.replay.variation);
    const later = CAPTURED.replay.inputs.find((input) => input.tick > 0)!;
    expect(() => applyArenaReplayInput(game, later, 7)).toThrow(/recorded at tick .*replay is at tick 0/);
  });

  it("refuses an input whose recorded checkpoint is not where the engine lands", () => {
    const game = new RestaurantGame(CAPTURED.seed, CAPTURED.replay.variation);
    const forged = { ...structuredClone(CAPTURED.replay.inputs[0]!), stateHash: `sha256:${"4".repeat(64)}` };
    expect(() => applyArenaReplayInput(game, forged, 0)).toThrow(/checkpoint mismatch at replay\.inputs\[0\]/);
