import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { exportTraceJsonl, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";

const ROOT = join(import.meta.dir, "..");
const FIXTURE = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");
const EXPORT_CLI = join(ROOT, "scripts/export-arena-trace.ts");
const REPLAY_CLI = join(ROOT, "scripts/replay-arena-trace.ts");

function run(script: string, ...args: string[]) {
  return spawnSync(process.execPath, [script, ...args], { encoding: "utf8", cwd: ROOT });
}

function fixtureTrace(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE, "utf8")) as RestaurantArenaTraceV3;
}

/** A throwaway directory for trace files the replay CLI reads off disk. */
function workspace(): string {
  return mkdtempSync(join(tmpdir(), "arena-trace-cli-"));
}

describe("export-arena-trace", () => {
  test("reports the checked-in fixture as current", () => {
    const result = run(EXPORT_CLI, "--check");
    expect(result.stdout).toContain("Fixture is current");
    expect(result.status).toBe(0);
  });

  test("writes the fixture, and flags it as stale until it is rewritten", () => {
    const original = readFileSync(FIXTURE, "utf8");
    try {
      const trace = fixtureTrace();
      trace.terminal.reason = "hand_edited";
      writeFileSync(FIXTURE, `${JSON.stringify(trace, null, 2)}\n`);

      // The CI guard has to notice: a fixture nobody regenerated is not evidence
      // of what the engine does today.
      const stale = run(EXPORT_CLI, "--check");
      expect(stale.status).toBe(1);
      expect(stale.stderr).toContain("Fixture is stale");
      expect(stale.stdout).not.toContain("Fixture is current");

      const written = run(EXPORT_CLI);
      expect(written.status).toBe(0);
      expect(written.stdout).toContain("Wrote");
      expect(written.stdout).toContain("contracts/fixtures/restaurant-arena-trace-v3.json");
      // Rewriting restores the exact bytes: the same shift exports the same trace.
      expect(readFileSync(FIXTURE, "utf8")).toBe(original);
    } finally {
      writeFileSync(FIXTURE, original);
    }
  });

  test("rejects an unknown flag", () => {
    const result = run(EXPORT_CLI, "--force");
    expect(result.status).toBe(2);
    expect(result.stderr).toContain("Usage");
  });
});

describe("replay-arena-trace", () => {
  test("passes on the fixture JSON export", () => {
    const result = run(REPLAY_CLI, FIXTURE);
    expect(result.stdout).toContain("Native replay passed");
    expect(result.status).toBe(0);
  });

  test("passes on a JSONL export of the same trace", () => {
    const directory = workspace();
    try {
      const path = join(directory, "trace.jsonl");
      writeFileSync(path, `${exportTraceJsonl(fixtureTrace())}\n`);
      const result = run(REPLAY_CLI, path);
      expect(result.stdout).toContain("Native replay passed");
      expect(result.status).toBe(0);
    } finally {
      rmSync(directory, { recursive: true, force: true });
    }
  });

  test("fails on a trace whose recorded outcome was edited", () => {
    const directory = workspace();
    try {
      const path = join(directory, "tampered.json");
      const trace = fixtureTrace();
      trace.terminal.reason = "user_quit";
      writeFileSync(path, JSON.stringify(trace));
      const result = run(REPLAY_CLI, path);
      expect(result.status).toBe(1);
      expect(result.stdout).not.toContain("Native replay passed");
      expect(result.stderr).toContain("Native replay failed");
      expect(result.stderr).toContain("terminal mismatch");
    } finally {
      rmSync(directory, { recursive: true, force: true });
    }
  });

  test("fails on a trace whose checkpoint hash was rewritten", () => {
    const directory = workspace();
    try {
      const path = join(directory, "forged.json");
      const trace = fixtureTrace();
      trace.replay.inputs[4]!.stateHash = `sha256:${"0".repeat(64)}`;
      writeFileSync(path, JSON.stringify(trace));
      const result = run(REPLAY_CLI, path);
      expect(result.status).toBe(1);
      expect(result.stderr).toContain("checkpoint mismatch");
    } finally {
      rmSync(directory, { recursive: true, force: true });
    }
  });

  test("fails on a malformed record, naming the field", () => {
    const directory = workspace();
    try {
      const path = join(directory, "malformed.json");
      const trace = fixtureTrace();
      (trace as { runKind: string }).runKind = "practice";
      writeFileSync(path, JSON.stringify(trace));
      const result = run(REPLAY_CLI, path);
      expect(result.status).toBe(1);
      expect(result.stdout).not.toContain("Native replay passed");
      expect(result.stderr).toContain("runKind");
    } finally {
      rmSync(directory, { recursive: true, force: true });
    }
  });

  test("fails on an unreadable or unnamed trace file", () => {
    expect(run(REPLAY_CLI, join(tmpdir(), "no-such-trace.json")).status).toBe(1);
    const noArgs = run(REPLAY_CLI);
    expect(noArgs.status).toBe(2);
    expect(noArgs.stderr).toContain("Usage");
  });
});

